import os
from typing import Any, Dict, List, Optional

from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient


def _to_number(value: Any) -> Optional[float]:
    if value is None:
        return None
    try:
        if hasattr(value, "value"):
            value = value.value
        if isinstance(value, (int, float)):
            return float(value)
        s = str(value).strip().replace(",", "")
        if not s:
            return None
        return float(s)
    except Exception:
        return None


def _get_field(fields: Dict[str, Any], *names: str) -> Any:
    for name in names:
        if name in fields and fields[name] is not None:
            return fields[name]
    lower_map = {str(k).lower(): v for k, v in fields.items()}
    for name in names:
        v = lower_map.get(name.lower())
        if v is not None:
            return v
    return None


def _field_content(field: Any) -> Any:
    if field is None:
        return None
    if isinstance(field, dict):
        return field.get("valueString") or field.get("content") or field.get("value") or field.get("text")
    for attr in ("value_string", "value_number", "content", "value", "text"):
        if hasattr(field, attr):
            v = getattr(field, attr)
            if v is not None:
                return v
    return field


def _field_confidence(field: Any) -> Optional[float]:
    if field is None:
        return None
    if isinstance(field, dict):
        return _to_number(field.get("confidence"))
    return _to_number(getattr(field, "confidence", None))


def _extract_items(items_value: Any) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []
    if not items_value:
        return items

    raw_items = items_value if isinstance(items_value, list) else getattr(items_value, "value_array", None) or []
    for item in raw_items:
        fields = {}
        if isinstance(item, dict):
            fields = item.get("valueObject") or item.get("value_object") or item.get("fields") or item
        else:
            fields = getattr(item, "value_object", None) or getattr(item, "fields", None) or {}

        if hasattr(fields, "items"):
            fields_dict = dict(fields.items())
        else:
            fields_dict = fields if isinstance(fields, dict) else {}

        description_field = _get_field(fields_dict, "Description", "Item", "Name", "ProductCode")
        quantity_field = _get_field(fields_dict, "Quantity")
        unit_field = _get_field(fields_dict, "UnitPrice", "Unit Price")
        total_field = _get_field(fields_dict, "Amount", "TotalPrice", "Price", "Total")

        items.append(
            {
                "description": _field_content(description_field),
                "quantity": _to_number(_field_content(quantity_field)),
                "unit_price": _to_number(_field_content(unit_field)),
                "total": _to_number(_field_content(total_field)),
                "confidence": max(
                    filter(
                        None,
                        [
                            _field_confidence(description_field),
                            _field_confidence(quantity_field),
                            _field_confidence(unit_field),
                            _field_confidence(total_field),
                        ],
                    ),
                    default=None,
                ),
            }
        )
    return items


def extract_receipt(path: str) -> Dict[str, Any]:
    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")
    if not endpoint or not key:
        raise ValueError("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY are required")

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    with open(path, "rb") as f:
        poller = client.begin_analyze_document(
            model_id="prebuilt-invoice",
            body=f,
            content_type="application/octet-stream",
        )
    result = poller.result()

    doc = result.documents[0] if getattr(result, "documents", None) else None
    fields = getattr(doc, "fields", {}) if doc else {}

    merchant_field = _get_field(fields, "MerchantName", "VendorName", "SupplierName", "RecipientName")
    tax_field = _get_field(fields, "TotalTax", "Tax")
    total_field = _get_field(fields, "InvoiceTotal", "Total")
    items_field = _get_field(fields, "Items", "LineItems")

    return {
        "merchant": _field_content(merchant_field),
        "tax": _to_number(_field_content(tax_field)),
        "total": _to_number(_field_content(total_field)),
        "items": _extract_items(items_field),
    }
